def color_code(value: Optional[str], background: bool) -> str:
    if not value:
        return ""
    v = str(value).strip().strip('"').strip("'")
    if not v:
        return ""
    if v in ("default", "none"):
        return ""
    if re.fullmatch(r"#[0-9a-fA-F]{6}", v):
        r = int(v[1:3], 16); g = int(v[3:5], 16); b = int(v[5:7], 16)
        return f"\033[{48 if background else 38};2;{r};{g};{b}m"
    m = re.fullmatch(r"rgb\(\s*([^,]+)\s*,\s*([^,]+)\s*,\s*([^,]+)\s*\)", v)
    if m:
        parts = []
        for p in m.groups():
            p = p.strip()
            try:
