            if part:
                bases.append(part)
    gr = os.environ.get("GOROOT") or go_env_value("GOROOT")
    if gr:
        bases.append(gr)
    home = os.environ.get("HOME")
    if home:
        bases.append(home)
    paths: List[str] = []
    for b in bases:
        for n in names:
            paths.append(os.path.join(b, n))
    return paths

def go_env_value(name: str) -> str:
    try:
        cp = subprocess.run(["go", "env", name], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, check=False, text=True)
        if cp.returncode == 0:
            return cp.stdout.strip()
    except Exception:
        pass
    return ""

def load_config() -> Config:
    cfg = default_config()
    for path in config_paths():
        if os.path.isfile(path):
            parse_config_file(path, cfg)
    if cfg.labelType not in ("long", "short"):
        cfg.labelType = "none"
    return cfg

def parse_config_file(path: str, cfg: Config) -> None:
    section: Optional[str] = None
    try:
        lines = open(path, "r", encoding="utf-8").read().splitlines()
    except Exception:
        return
    for raw in lines:
        if not raw.strip() or raw.lstrip().startswith("#"):
            continue
        indent = len(raw) - len(raw.lstrip(" "))
        line = raw.strip()
        if indent == 0:
            section = None
            if ":" not in line:
                continue
            key, val = line.split(":", 1)
            key = key.strip(); val = val.strip()
            if key in STYLE_NAMES:
                section = key
                if val.startswith("{") and val.endswith("}"):
                    # Very small concession to inline maps: key: {bold: true, foreground: red}
                    inner = val[1:-1].strip()
                    for part in inner.split(','):
                        if ':' in part:
                            k, v = part.split(':', 1)
                            apply_style_key(getattr(cfg, key), k.strip(), v.strip())
                continue
            if key == "removals":
                section = "removals"
                continue
            if key == "labelType":
                cfg.labelType = parse_value(val)
            elif key == "coverThreshold":
                try:
                    cfg.coverThreshold = float(parse_value(val))
                except ValueError:
                    pass
            elif key == "leaveTestPrefix":
                cfg.leaveTestPrefix = parse_bool(val)
            continue
        if section in STYLE_NAMES:
            if ":" in line:
                key, val = line.split(":", 1)
                apply_style_key(getattr(cfg, section), key.strip(), val.strip())
        elif section == "removals":
            if line.startswith("-"):
                pat = parse_value(line[1:].strip())
                cfg.removals.append(pat)

class Formatter:
    def __init__(self, cfg: Config):
        self.cfg = cfg
        self.current = Style()
        self.file_re = re.compile(r"([A-Za-z0-9_./\\-]*\.go)(:\d+(?::\d+)?)")

    def label(self, kind: str) -> str:
        t = self.cfg.labelType
        if t == "long":
            return {
                "build": "BUILD| ", "start": "START| ", "pass": "PASS | ",
                "fail": "FAIL | ", "skip": "SKIP | ", "cover": "COVER| ",
                "detail": "     | ",
            }.get(kind, "     | ")
        if t == "short":
            return {
                "build": "!! ", "start": ">  ", "pass": "o  ",
                "fail": "x  ", "skip": "-  ", "cover": "%  ",
                "detail": "   ",
            }.get(kind, "   ")
        return ""

    def style_text(self, style: Style, text: str) -> str:
        if style.hide:
            return ""
        codes = style.codes()
        if codes:
            return codes + text + RESET
        return text

    def nested_file_text(self, outer: Style, text: str) -> str:
        if outer.hide:
            return ""
        outer_codes = outer.codes()
        out: List[str] = []
        if outer_codes:
            out.append(outer_codes)
        pos = 0
        any_match = False
        for m in self.file_re.finditer(text):
            any_match = True
            out.append(text[pos:m.start()])
            fc = self.cfg.fileStyle.codes()
            lc = self.cfg.lineStyle.codes()
            if not self.cfg.fileStyle.hide:
                if fc:
                    out.append(fc + m.group(1) + RESET)
                else:
                    out.append(m.group(1))
            if not self.cfg.lineStyle.hide:
                if lc:
                    out.append(lc + m.group(2) + RESET)
                else:
                    out.append(m.group(2))
            if outer_codes:
                out.append(outer_codes)
            pos = m.end()
        out.append(text[pos:])
        if outer_codes:
            out.append(RESET)
        # If there were no matches this is equivalent to a simple wrapped line.
        return "".join(out)

    def clean_name(self, name: str) -> str:
        if not self.cfg.leaveTestPrefix and name.startswith("Test"):
            return name[4:]
        return name

    def indent_for_name(self, name: str) -> str:
        return "  " * name.count("/")

    def emit_normal(self, kind: str, style: Style, content: str, update: bool = True) -> str:
        if update:
            self.current = style
        return self.nested_file_text(style, self.label(kind) + content) + ("\n" if not style.hide else "")

    def emit_build(self, content: str) -> str:
        st = self.cfg.buildStyle
        self.current = st
        if st.hide:
            return ""
        # Build package header deliberately keeps the newline inside the styled span.
        return self.nested_file_text(st, self.label("build") + content + "\n")

    def emit_detail(self, content: str) -> str:
        st = self.current
        if st.hide:
            return ""
        return self.nested_file_text(st, self.label("detail") + content) + "\n"

    def format_line(self, line: str) -> str:
        for pat in self.cfg.removals:
            try:
                line = re.sub(pat, "", line)
            except re.error:
                pass
        if line == "":
            return ""

        if line.startswith("# "):
            return self.emit_build(line[2:])

        m = re.match(r"^=== RUN   (Test.*)$", line)
        if m:
            rawname = m.group(1)
            name = self.clean_name(rawname)
            return self.emit_normal("start", self.cfg.startStyle, self.indent_for_name(rawname) + name)

        m = re.match(r"^--- (PASS|FAIL|SKIP): (Test\S*)(.*)$", line)
        if m:
            status, rawname, suffix = m.group(1), m.group(2), m.group(3)
            name = self.clean_name(rawname)
            content = self.indent_for_name(rawname) + name + suffix
            if status == "PASS":
                return self.emit_normal("pass", self.cfg.passStyle, content)
            if status == "FAIL":
                return self.emit_normal("fail", self.cfg.failStyle, content)
            return self.emit_normal("skip", self.cfg.skipStyle, content)

        if line.strip() == "PASS":
            st = self.cfg.passPackageStyle
            if st.hide:
                return ""
            return self.style_text(st, "PASS") + "\n"
        if line.strip() == "FAIL":
            st = self.cfg.failPackageStyle
            if st.hide:
                return ""
            return self.style_text(st, "FAIL") + "\n"

        m = re.match(r"^coverage: (\d+\.\d)% of statements$", line)
        if m:
            pct_s = m.group(1)
            pct = float(pct_s)
            n = int(pct / 10.0)
            if n < 0: n = 0
            if n > 10: n = 10
            bar = "#" * n + "_" * (10 - n)
            st = self.cfg.coveredStyle if pct >= self.cfg.coverThreshold else self.cfg.uncoveredStyle
            # Coverage lines do not change the inherited style.
            if st.hide:
                return ""
            return self.nested_file_text(st, self.label("cover") + f"{pct_s}% [{bar}]") + "\n"

        m = re.match(r"^ok\s+(\S+)\s+\S+(?:\s+(coverage: \d+\.\d% of statements))?\s*$", line)
        if m:
            pkg = m.group(1)
            cov = m.group(2)
            content = pkg + " " + (cov if cov else "")
            return self.emit_normal("pass", self.cfg.passStyle, content)

        m = re.match(r"^FAIL(\s+.+)$", line)
        if m:
            return self.emit_normal("fail", self.cfg.failStyle, m.group(1))

        m = re.match(r"^\?\s+(.+\[no test files\])$", line)
        if m:
            return self.emit_normal("skip", self.cfg.skipStyle, m.group(1))

        return self.emit_detail(line)

    def format_text(self, text: str) -> str:
        out: List[str] = []
        # Go's scanner ignores empty lines and treats a missing final newline like a line.
        for line in text.splitlines():
            out.append(self.format_line(line))
        return "".join(out)

def color_enabled() -> bool:
    return bool(os.environ.get("RICHGO_FORCE_COLOR")) or sys.stdout.isatty()

def run_testfilter() -> int:
    data = sys.stdin.buffer.read()
    if not color_enabled():
        # Observed non-color testfilter behavior: copy input and append a newline to
        # both stdout and stderr, regardless of whether stdin was empty.
        sys.stdout.buffer.write(data + b"\n")
        sys.stdout.buffer.flush()
        sys.stderr.buffer.write(b"\n")
        sys.stderr.buffer.flush()
        return 0
    text = data.decode("utf-8", "replace")
    cfg = load_config()
    sys.stdout.write(Formatter(cfg).format_text(text))
    sys.stdout.flush()
    return 0

def filter_bytes_to_stream(data: bytes, stream, cfg: Config) -> None:
    text = data.decode("utf-8", "replace")
    stream.write(Formatter(cfg).format_text(text))
    stream.flush()

def run_go_test(args: List[str]) -> int:
    if not color_enabled():
        try:
            os.execvp("go", ["go", "test"] + args)
        except FileNotFoundError:
            print("go: command not found", file=sys.stderr)
            return 127
    cfg = load_config()
    try:
        cp = subprocess.run(["go", "test"] + args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False)
    except FileNotFoundError:
        print("go: command not found", file=sys.stderr)
        return 127
    filter_bytes_to_stream(cp.stdout, sys.stdout, cfg)
    # stderr is filtered too, but with its own fresh formatter state.
    filter_bytes_to_stream(cp.stderr, sys.stderr, cfg)
    return cp.returncode

def exec_go(args: List[str]) -> int:
    try:
        os.execvp("go", ["go"] + args)
    except FileNotFoundError:
        print("go: command not found", file=sys.stderr)
        return 127

def main(argv: List[str]) -> int:
    if argv and argv[0] == "testfilter":
        return run_testfilter()
    if argv and argv[0] == "test":
        return run_go_test(argv[1:])
    return exec_go(argv)

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
